Map<String, BigDecimal> balances = new HashMap<>();
// ... populated with 100K accounts

// ═══ FAST: entrySet() — one pass, no re-lookup ═══
for (Map.Entry<String, BigDecimal> entry : balances.entrySet()) {
    String accountId = entry.getKey();       // O(1) — field access
    BigDecimal balance = entry.getValue();   // O(1) — field access
    // NO hash computation, NO bucket lookup!
}
// Total: n iterations, 0 hash lookups

// ═══ SLOW: keySet() + get() — double lookup ═══
for (String accountId : balances.keySet()) {
    BigDecimal balance = balances.get(accountId);  // REHASH + bucket lookup!
    // For each key: hash(accountId) → find bucket → walk chain → equals() check
}
// Total: n iterations + n hash lookups = 2n work!

// ═══ MODERN: forEach (Java 8) — cleanest and fast ═══
balances.forEach((accountId, balance) -> {
    // Same as entrySet internally — no re-lookup!
    process(accountId, balance);
});

// ═══ STREAMS ═══
balances.entrySet().stream()
    .filter(e -> e.getValue().compareTo(new BigDecimal("100000")) > 0)
    .forEach(e -> log.info("High balance: {} = {}", e.getKey(), e.getValue()));
```

