package com.bank.iteration;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class EntrySetVsKeySetTest {

    @Test
    void entrySet_givenKeyAndValueDirectly() {
        Map<String, BigDecimal> balances = Map.of(
            "SAV2001", new BigDecimal("75000"),
            "CUR3001", new BigDecimal("120000"));

        Map<String, BigDecimal> result = new HashMap<>();
        for (Map.Entry<String, BigDecimal> entry : balances.entrySet()) {
            result.put(entry.getKey(), entry.getValue());  // direct access!
        }
        assertThat(result).hasSize(2);
    }

    @Test
    void keySetPlusGet_doubleWork() {
        Map<String, BigDecimal> balances = Map.of(
            "SAV2001", new BigDecimal("75000"),
            "CUR3001", new BigDecimal("120000"));

        Map<String, BigDecimal> result = new HashMap<>();
        for (String key : balances.keySet()) {
            result.put(key, balances.get(key));  // re-lookup for each key!
        }
        assertThat(result).hasSize(2);
        // Same result, more work.
    }

    @Test
    void forEach_cleanestSyntax() {
        Map<String, BigDecimal> balances = Map.of(
            "SAV2001", new BigDecimal("75000"),
            "CUR3001", new BigDecimal("120000"));

        List<String> summaries = new ArrayList<>();
        balances.forEach((id, bal) ->
            summaries.add(id + "=" + bal));
        assertThat(summaries).hasSize(2);
    }

    @Test
    void performance_entrySetVsKeySetGet() {
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < 200_000; i++) map.put("KEY-" + i, i);

        // entrySet:
        long t1 = System.nanoTime();
        long sum1 = 0;
        for (var entry : map.entrySet()) sum1 += entry.getValue();
        long entryMs = (System.nanoTime() - t1) / 1_000_000;

        // keySet + get:
        long t2 = System.nanoTime();
        long sum2 = 0;
        for (String key : map.keySet()) sum2 += map.get(key);
        long keySetMs = (System.nanoTime() - t2) / 1_000_000;

        System.out.println("entrySet: " + entryMs + "ms, keySet+get: " + keySetMs + "ms");
        assertThat(sum1).isEqualTo(sum2);
        // entrySet typically 30-50% faster!
    }
}
