class StatementService {
  Map<String,BigDecimal> balances;   // HashMap 200K

  // GOOD — single pass, no re-lookup
  void writeFast(Writer w) {
    for (Map.Entry<String,BigDecimal> e : balances.entrySet())
      w.line(e.getKey(), e.getValue());   // direct field access
  }
  // BAD — hash + bucket walk per key
  void writeSlow(Writer w) {
    for (String k : balances.keySet())
      w.line(k, balances.get(k));         // re-hash every key
  }
  // Java 8 — cleanest, same perf as entrySet
  void writeLambda(Writer w) {
    balances.forEach((k,v) -> w.line(k,v));
  }
}
